INSERT INTO public.fsr_lob_templates (company, lob, template_name, version, body_html, notes, is_active)
VALUES (
  'Acuere',
  'Extended Warranty',
  'Production',
  1,
  $body$<!DOCTYPE html>
<!--
  Extended Warranty FSR — ACUERE letterhead.

  Source: derived from production sample AS-1752-25-26 in `FSR formats/`
  (Toyota True Warranty, Fortuner, Oriental Insurance).

  Goes into the portal table `fsr_lob_templates` as:
    company='Acuere' lob='Extended Warranty' template_name='Production' version=1

  Structurally identical to extended-warranty--nisla.html — only the
  letterhead, IRDAI license, and accent colour differ.
-->
<html lang="en">
<head>
  <meta charset="utf-8" />
  <title>Extended Warranty FSR — {{claim.ref_number}}</title>
  <style>
    @page { size: A4; margin: 16mm; }
    body { font-family: 'Times New Roman', Times, serif; font-size: 11pt; color: #111; line-height: 1.45; }

    .letterhead { text-align: center; border-bottom: 2px solid #1a7ab5; padding-bottom: 8px; margin-bottom: 12px; }
    .letterhead h1 { margin: 0; font-size: 13pt; color: #1a7ab5; }
    .letterhead .lob-strip { font-size: 9pt; color: #475569; margin-top: 2px; letter-spacing: 0.4px; }
    .letterhead .sub { font-size: 9pt; color: #475569; margin-top: 2px; }

    .cover { text-align: center; margin: 18px 0 12px; }
    .cover .doc-title { font-size: 16pt; font-weight: 700; color: #1a7ab5; letter-spacing: 0.5px; }
    .cover .ref { font-size: 10pt; margin-top: 6px; color: #475569; }
    .cover .vehicle { font-size: 12pt; font-weight: 700; margin-top: 14px; }
    .cover .vin { font-size: 11pt; margin-top: 4px; }
    .cover .insured { font-size: 11pt; margin-top: 6px; }
    .cover .policy-line { font-size: 10pt; margin-top: 4px; color: #475569; }
    .cover .plan { font-size: 11pt; font-style: italic; margin-top: 10px; color: #1a7ab5; }

    .doc-sub { text-align: center; font-size: 10pt; color: #475569; font-style: italic; margin: 12px 0; }

    .to-block { font-size: 10pt; margin: 12px 0; line-height: 1.45; }
    h2 { font-size: 11pt; color: #1a7ab5; border-bottom: 1px solid #cbd5e1; padding-bottom: 2px; margin: 14px 0 6px; text-transform: uppercase; letter-spacing: 0.3px; }

    table.kv { width: 100%; border-collapse: collapse; margin: 6px 0 12px; }
    table.kv td { padding: 4px 6px; vertical-align: top; border: 1px solid #e2e8f0; font-size: 10pt; }
    table.kv td.lbl { width: 4%; font-weight: 600; color: #475569; text-align: center; }
    table.kv td.k   { width: 28%; font-weight: 600; color: #475569; }

    table.totals { width: 70%; margin: 12px 0 12px auto; border-collapse: collapse; font-size: 11pt; }
    table.totals td { padding: 4px 8px; }
    table.totals tr.grand td { font-weight: 700; border-top: 2px solid #1a7ab5; padding-top: 8px; font-size: 12pt; }
    table.totals td.num { text-align: right; }

    .signoff { margin-top: 30px; padding-top: 12px; border-top: 1px dashed #94a3b8; }
    .footer { margin-top: 24px; font-size: 8pt; color: #64748b; text-align: center; border-top: 1px solid #e2e8f0; padding-top: 6px; }
    p { margin: 6px 0; }
    .small { font-size: 9pt; color: #475569; }
    .annex { page-break-before: always; }
  </style>
</head>
<body>

<div class="letterhead">
  <h1>ACUERE SURVEYORS</h1>
  <div class="lob-strip">Fire &nbsp;|&nbsp; Misc. &nbsp;|&nbsp; Engg. &nbsp;|&nbsp; Marine Cargo &nbsp;|&nbsp; Motor</div>
  <div class="sub">IRDAI Licence: IRDAI/IND/SLA-85225 (Exp. 02/03/2028)</div>
  <div class="sub">A-45, 401, Gurukrupa, Gokuldham, Goregaon (E), Mumbai – 400063</div>
  <div class="sub">Contact: 9892976754, 9892596754 &nbsp;·&nbsp; Email: niteennathani@gmail.com, acueresurveyors@gmail.com</div>
</div>

<div class="cover">
  <div class="doc-title">EXTENDED WARRANTY REPORT</div>
  <div class="ref">Ref. No: <strong>{{claim.ref_number}}</strong> &nbsp;·&nbsp; Date: {{date_today}}</div>
  <div class="vehicle">REPORTED LOSS TO VEHICLE NO. {{narrative.registration_no}}</div>
  <div class="vin">VIN NUMBER &mdash; {{narrative.vin}}</div>
  <div class="insured">INSURED: <strong>{{claim.insured_name}}</strong></div>
  <div class="policy-line">{{claim.insurer_name}}</div>
  <div class="policy-line">EXTENDED WARRANTY INSURANCE POLICY NO &mdash; {{claim.policy_number}}</div>
  <div class="plan">{{narrative.plan_name}}</div>
</div>

<div style="page-break-after: always;"></div>

<div class="letterhead">
  <h1>ACUERE SURVEYORS</h1>
  <div class="sub">IRDAI Licence: IRDAI/IND/SLA-85225 (Exp. 02/03/2028)</div>
</div>

<div class="doc-sub">EXTENDED WARRANTY REPORT (WITHOUT PREJUDICE)</div>

<div class="to-block">
  <strong>To,</strong><br/>
  The Claim In-Charge<br/>
  {{claim.insurer_name}}<br/>
  {{narrative.insurer_office_address}}
</div>

<p><strong>Subject:</strong> Reported claim under Extended Warranty of VIN No. {{narrative.vin}},
   Vehicle No. {{narrative.registration_no}}, Insured: {{claim.insured_name}},
   Policy No: {{claim.policy_number}} || Claim File No: {{claim.claim_number}}</p>

<p>Dear Sir,</p>
<p>Pursuant to valued instruction received from {{narrative.instructions_received_from}} on
   {{claim.date_of_intimation}} for survey and loss assessment of the below mentioned claim,
   we made immediate contact with the insured&rsquo;s representative and conducted the survey
   as per the details below.</p>

<h2>1. Claim Details</h2>
<p class="small">Now we are submitting our final survey and loss assessment report which is
   based on the following observations and documents provided.</p>
<table class="kv">
  <tr><td class="k">Insured</td><td>{{claim.insured_name}}<br/><span class="small">{{narrative.insured_address}}</span></td></tr>
  <tr><td class="k">Insurer</td><td>{{claim.insurer_name}}<br/><span class="small">{{narrative.insurer_office_address}}</span></td></tr>
  <tr><td class="k">Policy No.</td><td>{{claim.policy_number}}</td></tr>
  <tr><td class="k">Claim File No.</td><td>{{claim.claim_number}}</td></tr>
  <tr><td class="k">Person Contacted</td><td>{{narrative.person_contacted}}</td></tr>
  <tr><td class="k">Estimated Loss Amount</td><td>{{loss_sheet.gross_loss_inr}}</td></tr>
  <tr><td class="k">Claim Type</td><td>Claim under Extended Warranty of VIN No. {{narrative.vin}}</td></tr>
</table>

<h2>2. Certificate / Vehicle Particulars</h2>
<table class="kv">
  <tr><td class="lbl">a</td><td class="k">Name of Customer</td><td>{{narrative.customer_name}}</td></tr>
  <tr><td class="lbl">b</td><td class="k">Registration No.</td><td>{{narrative.registration_no}}</td></tr>
  <tr><td class="lbl">c</td><td class="k">Date of Registration</td><td>{{narrative.date_of_registration}}</td></tr>
  <tr><td class="lbl">d</td><td class="k">Make</td><td>{{narrative.vehicle_make}}</td></tr>
  <tr><td class="lbl">e</td><td class="k">Model / Fuel Type</td><td>{{narrative.vehicle_model}}</td></tr>
  <tr><td class="lbl">f</td><td class="k">Chassis No.</td><td>{{narrative.vin}}</td></tr>
  <tr><td class="lbl">g</td><td class="k">Engine No.</td><td>{{narrative.engine_no}}</td></tr>
  <tr><td class="lbl">h</td><td class="k">Odometer Reading</td><td>{{narrative.odometer}}</td></tr>
  <tr><td class="lbl">i</td><td class="k">Plan</td><td>{{narrative.plan_name}}</td></tr>
  <tr><td class="lbl">j</td><td class="k">Certificate No.</td><td>{{narrative.certificate_no}}</td></tr>
  <tr><td class="lbl">k</td><td class="k">Certificate Validity</td><td>{{narrative.certificate_validity}}</td></tr>
  <tr><td class="lbl">l</td><td class="k">Product</td><td>{{narrative.product_description}}</td></tr>
  <tr><td class="lbl">m</td><td class="k">Terms &amp; Conditions</td><td>{{narrative.terms_and_conditions}}</td></tr>
</table>

<h2>3. Our Survey / Inspection / Findings</h2>
<p>{{narrative.observations}}</p>

<p class="small">Tax Invoice was furnished by the dealer (copy enclosed):</p>
<ul class="small">
  <li>Tax Invoice No: {{narrative.tax_invoice_no}}</li>
  <li>Tax Invoice Date: {{narrative.tax_invoice_date}}</li>
  <li>Invoice Amount: {{narrative.tax_invoice_amount_inr}}</li>
</ul>

<h2>4. Assessment of Loss</h2>
<p>We have assessed the loss based on the physical observation of the damages and
   documents / details submitted by the insured.</p>
<p>{{narrative.assessment_basis}}</p>
<p>We have not considered the GST component in our assessment, as the insured would be
   eligible to take GST credit.</p>

<table class="totals">
  <tr><td>Gross Assessed Loss Amount</td><td class="num">{{loss_sheet.gross_loss_inr}}</td></tr>
  <tr><td>Less: GST Amount</td><td class="num">{{loss_sheet.gst_amount_inr}}</td></tr>
  <tr><td>Total</td><td class="num">{{loss_sheet.after_gst_inr}}</td></tr>
  <tr><td>Less: Not Covered</td><td class="num">{{loss_sheet.not_covered_inr}}</td></tr>
  <tr class="grand"><td>Net Adjusted Loss Amount</td><td class="num">{{loss_sheet.net_adjusted_loss_inr}}</td></tr>
</table>

<p>(<strong>{{loss_sheet.net_adjusted_loss_words}}</strong>) subject to policy terms,
   conditions and final approval by the insurer.</p>

<h2>5. Conclusion</h2>
<p>In view of the above, as per the Manufacturer Guidelines / Manual, the defective part has
   been replaced with a new one. The same may be considered under extended warranty, subject
   to coverage of the vehicle in the policy and as per the terms and conditions of the policy
   issued.</p>

<p><strong>Note:</strong></p>
<ul class="small">
  <li>Insurers are advised to check the Annexure of the policy and verify if the particular vehicle was declared to the insurer at the time of taking the policy or agreed in the policy.</li>
  <li>Insurers are advised to check the proof of payment (made by the insured to the dealer) before indemnifying the claimed loss.</li>
</ul>

<p>This report is issued without prejudice and is subject to the terms &amp; conditions of
   the policy of insurance issued to and held by the insured, reserving our rights to alter /
   amend unintended error, if any. This concludes our extended warranty report which has been
   issued for perusal of the insurance company.</p>

<p class="small"><em>(For discretion of insurer &amp; their legal advisers only)</em></p>

<div class="signoff">
  <p style="margin-top: 22px;">
    <strong>Authorized Signatory</strong><br/>
    <strong>{{signer.name}}</strong> (Surveyor)<br/>
    IRDAI Licence: {{signer.license}}<br/>
    For Acuere Surveyors<br/>
    <span class="small">Ref No: {{claim.ref_number}} &nbsp;·&nbsp; Date: {{date_today}}</span>
  </p>
</div>

<div class="footer">
  Generated by NISLA Portal &nbsp;·&nbsp; Surveyor reference {{claim.ref_number}}
</div>

</body>
</html>
$body$,
  'Real-sample-aligned (AS-1752)',
  true
)
