INSERT INTO public.fsr_lob_templates (company, lob, template_name, version, body_html, notes, is_active)
VALUES (
  'NISLA',
  'Marine Cargo',
  'ILA',
  1,
  $body$<!DOCTYPE html>
<!--
  Initial Loss Advice (ILA) — Marine Cargo. Firm-agnostic skeleton; the
  letterhead block at top reads from {{company.*}} so the same template
  works for both NISLA and Acuere.

  The ILA is the 72-hour preliminary report issued before the full
  survey is complete (per IRDAI Surveyors Regs 2015 — see
  CLAUDE.md §13). It captures: cause-of-loss preliminary view,
  estimated reserve, immediate observations, list of documents
  pending. It does NOT recommend a settlement amount.

  Goes into the portal table `fsr_lob_templates` as:
    company=<NISLA|Acuere> lob='Marine Cargo' template_name='ILA' version=1

  (Same lob as the full FSR, just a different template_name.)
-->
<html lang="en">
<head>
  <meta charset="utf-8" />
  <title>ILA — Marine Cargo — {{claim.ref_number}}</title>
  <style>
    @page { size: A4; margin: 16mm; }
    body { font-family: 'Times New Roman', Times, serif; font-size: 11pt; color: #111; line-height: 1.45; }

    .letterhead { text-align: center; border-bottom: 2px solid {{company.accent_color}}; padding-bottom: 8px; margin-bottom: 12px; }
    .letterhead h1 { margin: 0; font-size: 14pt; color: {{company.accent_color}}; }
    .letterhead .sub { font-size: 9pt; color: #475569; margin-top: 2px; }

    .ref-line { display: flex; justify-content: space-between; font-size: 10pt; margin: 8px 0; }
    .doc-title { text-align: center; font-size: 13pt; font-weight: 700; margin: 14px 0 4px; color: {{company.accent_color}}; letter-spacing: 0.4px; }
    .doc-sub { text-align: center; font-size: 10pt; color: #475569; font-style: italic; margin-bottom: 12px; }

    h2 { font-size: 11pt; color: {{company.accent_color}}; border-bottom: 1px solid #cbd5e1; padding-bottom: 2px; margin: 14px 0 6px; text-transform: uppercase; letter-spacing: 0.3px; }

    table.kv { width: 100%; border-collapse: collapse; margin: 6px 0 12px; }
    table.kv td { padding: 4px 6px; vertical-align: top; border: 1px solid #e2e8f0; font-size: 10pt; }
    table.kv td.k { width: 30%; font-weight: 600; color: #475569; }

    .signoff { margin-top: 30px; padding-top: 12px; border-top: 1px dashed #94a3b8; }
    .footer { margin-top: 24px; font-size: 8pt; color: #64748b; text-align: center; border-top: 1px solid #e2e8f0; padding-top: 6px; }
    p { margin: 6px 0; }
    .small { font-size: 9pt; color: #475569; }
    .reserve { font-size: 13pt; font-weight: 700; color: {{company.accent_color}}; padding: 6px 0; }
  </style>
</head>
<body>

<div class="letterhead">
  <h1>{{company.name}}</h1>
  <div class="sub">{{company.license_line}}</div>
  <div class="sub">{{company.address_line}}</div>
</div>

<div class="ref-line">
  <span><strong>Ref. No:</strong> {{claim.ref_number}}</span>
  <span><strong>Date:</strong> {{date_today}}</span>
</div>

<div class="doc-title">INITIAL LOSS ADVICE (ILA) &mdash; MARINE CARGO</div>
<div class="doc-sub">(WITHOUT PREJUDICE)</div>

<p><strong>To,</strong><br/>
   The Manager,<br/>
   {{claim.insurer_name}}<br/>
   {{narrative.insurer_office_address}}</p>

<p><strong>Subject:</strong> Preliminary loss advice — Marine Cargo claim<br/>
   <span class="small">Policy No: {{claim.policy_number}} || Insured: {{claim.insured_name}} || Claim No: {{claim.claim_number}} || LR No: {{narrative.lr_no}}</span></p>

<p>Dear Sir,</p>
<p>Pursuant to your instructions received on {{claim.date_of_intimation}}, we have made
   immediate contact with the insured&rsquo;s representative and visited the loss site /
   warehouse for a preliminary inspection. This Initial Loss Advice records our
   first-look findings; a full Final Survey Report will follow once documentation and
   formal assessment are complete.</p>

<h2>1. Claim Summary</h2>
<table class="kv">
  <tr><td class="k">Insurer</td><td>{{claim.insurer_name}}</td></tr>
  <tr><td class="k">Insured</td><td>{{claim.insured_name}}</td></tr>
  <tr><td class="k">Policy No.</td><td>{{claim.policy_number}}</td></tr>
  <tr><td class="k">Type of Policy</td><td>{{claim.lob_subcategory}}</td></tr>
  <tr><td class="k">Sum Insured</td><td>{{loss_sheet.sum_insured_inr}}</td></tr>
  <tr><td class="k">Date of Loss</td><td>{{claim.date_loss}}</td></tr>
  <tr><td class="k">Date of Intimation</td><td>{{claim.date_of_intimation}}</td></tr>
  <tr><td class="k">Loss Location / Transit</td><td>{{narrative.transit}}</td></tr>
  <tr><td class="k">LR / Consignment</td><td>{{narrative.lr_no}} dated {{narrative.lr_date}}</td></tr>
  <tr><td class="k">Carrier</td><td>{{narrative.carrier}}</td></tr>
</table>

<h2>2. Preliminary Findings</h2>
<p>{{narrative.preliminary_findings}}</p>

<h2>3. Cause of Loss (Preliminary View)</h2>
<p>{{ila.preliminary_view}}</p>

<h2>4. Coverage Position (Preliminary)</h2>
<p>Subject to confirmation against the full policy schedule and final documentation,
   the loss <strong>{{ila.preliminary_admissibility_label}}</strong> appears to fall
   within the cover provided. {{ila.admissibility_reasoning}}</p>

<h2>5. Estimated Loss Reserve</h2>
<p>Based on the inspection and the documents seen so far, we recommend the insurer
   reserve approximately:</p>
<p class="reserve">{{loss_sheet.estimated_reserve_inr}}</p>
<p class="small">This is a preliminary, indicative figure only. The Net Adjusted Loss
   will be determined in the Final Survey Report after full documentation is reviewed
   and item-wise assessment is completed.</p>

<h2>6. Documents Pending from Insured</h2>
<p>{{narrative.documents_pending}}</p>

<h2>7. Next Steps</h2>
<p>{{narrative.next_steps}}</p>

<div class="signoff">
  <p style="margin-top: 22px;">
    <strong>Authorized Signatory</strong><br/>
    <strong>{{signer.name}}</strong> (Surveyor)<br/>
    IRDAI Licence: {{signer.license}}<br/>
    For {{company.name}}<br/>
    <span class="small">Date: {{date_today}}</span>
  </p>
</div>

<p class="small"><em>This Initial Loss Advice is issued without prejudice and is subject
   to the terms and conditions of the policy of insurance. The figures above are
   indicative; final assessment will be communicated via the Final Survey Report.</em></p>

<div class="footer">
  Generated by NISLA Portal &nbsp;·&nbsp; Surveyor reference {{claim.ref_number}}
</div>

</body>
</html>
$body$,
  'Initial Loss Advice — 72-hour preliminary',
  true
)
ON CONFLICT (company, lob, template_name, version) DO NOTHING;

