-->
<html lang="en">
<head>
  <meta charset="utf-8" />
  <title>ILA — Extended Warranty — {{claim.ref_number}}</title>
  <style>
    @page { size: A4; margin: 16mm; }
    body { font-family: 'Times New Roman', Times, serif; font-size: 11pt; color: #111; line-height: 1.45; }

    .letterhead { text-align: center; border-bottom: 2px solid {{company.accent_color}}; padding-bottom: 8px; margin-bottom: 12px; }
    .letterhead h1 { margin: 0; font-size: 14pt; color: {{company.accent_color}}; }
    .letterhead .sub { font-size: 9pt; color: #475569; margin-top: 2px; }

    .ref-line { display: flex; justify-content: space-between; font-size: 10pt; margin: 8px 0; }
    .doc-title { text-align: center; font-size: 13pt; font-weight: 700; margin: 14px 0 4px; color: {{company.accent_color}}; letter-spacing: 0.4px; }
    .doc-sub { text-align: center; font-size: 10pt; color: #475569; font-style: italic; margin-bottom: 12px; }

    h2 { font-size: 11pt; color: {{company.accent_color}}; border-bottom: 1px solid #cbd5e1; padding-bottom: 2px; margin: 14px 0 6px; text-transform: uppercase; letter-spacing: 0.3px; }

    table.kv { width: 100%; border-collapse: collapse; margin: 6px 0 12px; }
    table.kv td { padding: 4px 6px; vertical-align: top; border: 1px solid #e2e8f0; font-size: 10pt; }
    table.kv td.k { width: 30%; font-weight: 600; color: #475569; }

    .signoff { margin-top: 30px; padding-top: 12px; border-top: 1px dashed #94a3b8; }
    .footer { margin-top: 24px; font-size: 8pt; color: #64748b; text-align: center; border-top: 1px solid #e2e8f0; padding-top: 6px; }
    p { margin: 6px 0; }
    .small { font-size: 9pt; color: #475569; }
    .reserve { font-size: 13pt; font-weight: 700; color: {{company.accent_color}}; padding: 6px 0; }
  </style>
</head>
<body>

<div class="letterhead">
  <h1>{{company.name}}</h1>
  <div class="sub">{{company.license_line}}</div>
  <div class="sub">{{company.address_line}}</div>
</div>

<div class="ref-line">
  <span><strong>Ref. No:</strong> {{claim.ref_number}}</span>
  <span><strong>Date:</strong> {{date_today}}</span>
</div>

